from taf.ul.sc.generic_functionality import GenericFunctionality
from taf.ul.sc.util.decorators import GoToState
from taf.ul.sc.oam.emssim.commission import Commission
from taf.ul.sc.oam.emssim.software_update import SoftwareUpdate
from moler.device.device import DeviceFactory
from moler.util.moler_test import MolerTest


class Emssim(GenericFunctionality):

    def __init__(self,
                 device_name='EMSSIM1',     # type: 'Optional[str]'
                 device=None,               # type: 'Optional[EMSSim]'
                 autoconnect=False,         # type: 'Optional[bool]'
                 get_device=False           # type: 'Optional[bool]'
                 ):

        super(Emssim, self).__init__(device_name=device_name, device=device,
                                     autoconnect=autoconnect, get_device=get_device)
        if autoconnect:
            self.connect_to_emssim()

    @MolerTest.raise_background_exceptions(check_steps_end=True)
    def connect_to_emssim(self):
        """
        The keyword creates the AsiMgr device object based on the given device name.
        :return: nothing
        """
        self.connect()
        self.device.goto_state("EMSSIM")

        MolerTest.steps_end()

    @GoToState.emssim()
    def discover(self):
        """Executes discover command on emssim device"""
        return self.device.run(cmd_name="discover")

    @GoToState.emssim()
    def get_environment_info(self):
        """Executes env command on emssim device"""
        return self.device.run(cmd_name="env")

    @GoToState.emssim()
    def get_bts_connection_status(self):
        """Executes bts_connection_status command on emssim device"""
        return self.device.run(cmd_name="bts_connection_status")

    @GoToState.emssim()
    def get_states_of_manageable_objects(self, device=None):
        """Executes ls command on emssim device"""
        return self.device.run(cmd_name="ls", cmd_params={'device': device})

    @GoToState.emssim()
    def get_hw_info(self):
        """Executes hw_info command on emssim device"""
        return self.device.run(cmd_name="hw_info")

    @GoToState.emssim()
    def activate_ne3s(self, timeout=6 * 60):
        """Executes ne3s_activate command on emssim device.

        :param timeout: timeout for command
        """

        activate_cmd = self.device.get_cmd(cmd_name="ne3s_activate")
        return activate_cmd(timeout=timeout)

    @GoToState.emssim()
    def activate_rtpm_reporting(self, timeout=6 * 60):
        """Executes rtpm_activate command on emssim device.

        :param timeout: timeout for command
        """

        activate_cmd = self.device.get_cmd(cmd_name="rtpm_activate")
        return activate_cmd(timeout=timeout)

    @GoToState.emssim()
    def deactivate_rtpm_reporting(self, timeout=6 * 60):
        """Executes rtpm_deactivate command on emssim device.

        :param timeout: timeout for command
        """
        deactivate_cmd = self.device.get_cmd(cmd_name="rtpm_deactivate")
        return deactivate_cmd(timeout=timeout)

    @GoToState.emssim()
    def clean_rtpm_stats(self):
        """Executes rtpm_clean command on emssim device"""
        return self.device.run(cmd_name="rtpm_clean")

    @GoToState.emssim()
    def parse_rtpm_stats(self, mfilter=None, cfilter=None, short=False, quiet=False, timeout=60):
        """Executes rtpm_parse command on emssim device

        :param mfilter: To filter group of counters example: -mfilter M8051,M8011
        :param cfilter: To filter specific counters example: -cfilter M8051C26,M8051C23
        :param short: forces using abbreviated counters name instead of full name in parsed output
        :param quiet: quiet mode - do not print parsed data, only write to RTPM_Data.pl file
        :param timeout: timeout for command
        """

        parse_cmd = self.device.get_cmd(cmd_name="rtpm_parse",
                                        cmd_params={
                                            'mfilter': mfilter,
                                            'cfilter': cfilter,
                                            'short': short,
                                            'quiet': quiet,
                                        })

        return parse_cmd(timeout=timeout)

    @GoToState.emssim()
    def get_bts_info(self):
        """Executes bts_info command on emssim device"""
        return self.device.run(cmd_name="bts_info")

    def get_operational_state(self):
        """Executes bts_info command on emssim device and extracts operational state of LNBTS-ID"""
        bts_info_output = self.get_bts_info()
        bts_id = bts_info_output['bts_properties']['bts_id']
        operational_state = bts_info_output['states']['LNBTS-{}'.format(bts_id)]['operational']
        return operational_state

    def wait_for_onair(self, timeout=600, callback=None, callback_params={}):
        """
        Observer of emssim connection - waits for onAir state on LNBTS device
        :param callback: Function to run when event occurs
        :param callback_params: Callback function params
        :param timeout: After timeout error is raised
        :return: Event details
        """
        on_air = self.device.get_event(event_name="state_change_detected",
                                       event_params={"state": "onAir",
                                                     "till_occurs_times": 1,
                                                     "device_name": r"LNBTS-\d+"})
        if callback:
            on_air.add_event_occurred_callback(callback=callback, callback_params=callback_params)
        on_air_output = on_air(timeout=timeout)
        return on_air_output

    def wait_for_discover(self, timeout):
        """
        Observer of emssim connection - waits for succeeded discover operation
        :param timeout: After timeout error is raised
        :return: Event details
        """
        discover_event = self.device.get_event(event_name="discover_operation_succeeded")
        discover_event.start()
        discover_event_output = discover_event.await_done(timeout=timeout)

        return discover_event_output

    def wait_for_connection_lost(self, timeout, callback, callback_params):
        """
        Observer of emssim connection - executes callback callable if event occurs
        :param callback: Function to run when event occurs
        :param callback_params: Callback function params
        :param timeout: After timeout error is raised
        """
        lost_event = self.device.get_event(event_name="disconnected_btsom_link")
        lost_event.start()
        lost_event.add_event_occurred_callback(callback=callback, callback_params=callback_params)
        lost_event.await_done(timeout=timeout)

    def perform_full_commissioning(self, commissioning_file, wait_for_on_air=True):
        """
        Performing full commissioning and wait for onAir state if needed.
        :param commissioning_file: path to commissioning file
        :param wait_for_on_air: If set to True - wait till site goes to onAir state
        :return:
        """
        co = Commission(emssim=self.device,
                        emssim_ws=DeviceFactory.get_device(self.ws_name),
                        path_to_commissioning_file=commissioning_file)

        co.send_commissioning_file_to_emssim_workstation()
        co.perform_full_commissioning()
        if wait_for_on_air:
            self.wait_for_onair()

    def software_update(self, build_file, wait_for_on_air=True, activate=True):
        """
        Perform eNB software update and wait for onAir state if needed.

        :param build_file: path to build file
        :param wait_for_on_air: If set to True - wait till site goes to onAir state
        :param activate: flag for activation in sw_update command
        :return: None
        """
        sw_update = SoftwareUpdate(emssim=self,
                                   emssim_ws=DeviceFactory.get_device(self.ws_name),
                                   path_to_build_file=build_file,
                                   activate=activate)
        sw_update.download_build_file_to_emssim_workstation()
        sw_update.software_update()
        if wait_for_on_air:
            self.wait_for_onair()
            sw_update.calculate_on_air_wait_time()
        # TODO Add method to verify alarms before and after update
        return sw_update.get_time_report()

    @GoToState.emssim()
    def perform_recommissioning(self, params=[]):
        """
        Reconfigure eNB via EMSSIM.

        :param params: List containing dicts with cmd params.
                       Example: [{'object': 'LNBTS-211', 'attribute': 'act1xCsfb', 'value': 'True'}]
        :return: None
        """
        try:
            self.device.run(cmd_name="plan_create")
            for item in params:
                self.device.run(cmd_name="plan_edit",
                                cmd_params={'obj': item['object'], 'attr': item['attribute'], 'val': item['value']})
            self.device.run(cmd_name="plan_send")
        except Exception as exception:
            self.device.run(cmd_name="plan_destroy")
            raise exception

    def get_pm_stats_event(self, till_occurs_times=1, callback=None, callback_params={}):
        """
        Observer of emssim connection - waits for 'NE reports measurementFile ready for upload'
        :param till_occurs_times: number of event occurrence
        :param callback: Function to run when event occurs
        :param callback_params: Callback function params
        :return: event object
        """

        pm_stats = self.device.get_event(event_name="file_load_prepare",
                                         event_params={"file_type": "measurementFile",
                                                       "till_occurs_times": till_occurs_times})

        if callback:
            pm_stats.add_event_occurred_callback(callback=callback, callback_params=callback_params)

        return pm_stats

    def get_rtpm_stats_event(self, till_occurs_times=1, callback=None, callback_params={}):
        """
        Observer of emssim connection - waits for 'Received RTPM message'
        :param till_occurs_times: number of event occurrence
        :param callback: Function to run when event occurs
        :param callback_params: Callback function params
        :return: event object
        """

        pm_stats = self.device.get_event(event_name="received_rtpm_message",
                                         event_params={"till_occurs_times": till_occurs_times})

        if callback:
            pm_stats.add_event_occurred_callback(callback=callback, callback_params=callback_params)

        return pm_stats
